    /// Each fixture in `payload.invalid-examples.json` MUST be
    /// rejected by at least one of: serde deserialization, or
    /// JSON-Schema validation under the `validate` feature. The
    /// fixture file documents the producer-side bug class that
    /// each payload exemplifies; this generated test pins it.
    #[cfg(feature = "validate")]
    #[test]
    fn rejects_invalid_examples() {
        use crate::validate::ValidatedPayload;
        let fixtures: &[(&str, &str)] = &[
            (
                "`name` is lowercase.",
                "{\n  \"name\": \"Gadgets\",\n  \"namespace\": \"ns_01J8Z6Q4M2\",\n  \"visibility\": \"public\"\n}",
            ),
            (
                "`name` is one segment; the namespace supplies forge and owner.",
                "{\n  \"name\": \"acme/gadgets\",\n  \"namespace\": \"ns_01J8Z6Q4M2\",\n  \"visibility\": \"public\"\n}",
            ),
            (
                "`name` cannot start with a dot, which also rules out `.` and `..`.",
                "{\n  \"name\": \"..\",\n  \"namespace\": \"ns_01J8Z6Q4M2\",\n  \"visibility\": \"public\"\n}",
            ),
            (
                "`visibility` is `public` or `private`; forge-specific values such as `internal` are not modelled.",
                "{\n  \"name\": \"gadgets\",\n  \"namespace\": \"ns_01J8Z6Q4M2\",\n  \"visibility\": \"internal\"\n}",
            ),
            (
                "`visibility` is required: a forge default would make it depend on where the repository is created.",
                "{\n  \"name\": \"gadgets\",\n  \"namespace\": \"ns_01J8Z6Q4M2\"\n}",
            ),
            (
                "`owners`, when present, names at least one owner; omit it for the requester alone.",
                "{\n  \"name\": \"gadgets\",\n  \"namespace\": \"ns_01J8Z6Q4M2\",\n  \"owners\": [],\n  \"visibility\": \"public\"\n}",
            ),
            (
                "`owners` names each owner once.",
                "{\n  \"name\": \"gadgets\",\n  \"namespace\": \"ns_01J8Z6Q4M2\",\n  \"owners\": [\n    \"did:webvh:QmBobScid2:acme-vtc.example:bob\",\n    \"did:webvh:QmBobScid2:acme-vtc.example:bob\"\n  ],\n  \"visibility\": \"public\"\n}",
            ),
            (
                "An owner is a bare DID, never a DID URL such as a verification-method id.",
                "{\n  \"name\": \"gadgets\",\n  \"namespace\": \"ns_01J8Z6Q4M2\",\n  \"owners\": [\n    \"did:webvh:QmBobScid2:acme-vtc.example:bob#key-1\"\n  ],\n  \"visibility\": \"public\"\n}",
            ),
        ];
        for (i, (note, raw)) in fixtures.iter().enumerate() {
            let value: serde_json::Value = match serde_json::from_str(raw) {
                Ok(v) => v,
                Err(_) => continue,
            };
            let serde_ok = serde_json::from_value::<super::Payload>(value.clone()).is_ok();
            let schema_ok = super::Payload::validate_value(&value).is_ok();
            assert!(
                !(serde_ok && schema_ok),
                "invalid-example #{} ({:?}) was accepted by both serde and JSON Schema; \
                         the fixture's stated failure class is no longer caught:\n{}",
                i + 1,
                note,
                raw
            );
        }
    }
